def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, op_last = history[-1]

    op_c = 0
    op_d = 0
    for _, o in history:
        if o == 'C':
            op_c += 1
        else:
            op_d += 1

    my_d = 0
    for a, _ in history:
        if a == 'D':
            my_d += 1

    if op_d == 0:
        if my_d == 0:
            if n >= 10:
                return 'D'
            return 'C'
        else:
            return 'D'

    opp_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_def_streak += 1
        else:
            break

    my_def_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_def_streak += 1
        else:
            break

    if n == 98:
        if op_last == 'C' and opp_def_streak == 0:
            return 'C'
        return 'D'

    if op_last == 'D':
        if my_last == 'D' and opp_def_streak >= 2 and my_def_streak >= 2:
            if op_c > op_d:
                if rng.random() < 0.4:
                    return 'C'
            elif op_c > 0:
                if rng.random() < 0.2:
                    return 'C'
            else:
                if rng.random() < 0.1:
                    return 'C'
        elif my_last == 'C':
            recent = history[-5:] if n >= 5 else history
            recent_op_c = 0
            for _, o in recent:
                if o == 'C':
                    recent_op_c += 1
            if recent_op_c >= 2:
                if rng.random() < 0.5:
                    return 'C'
            elif recent_op_c == 1:
                if rng.random() < 0.2:
                    return 'C'
            else:
                if rng.random() < 0.05:
                    return 'C'
        return 'D'

    return 'C'
